            "continuous": false,
            "action": {
                "type": "apoli:execute_command",
                "command": "me jumped!"
            }
        },
        "key.attack",
        "key.use"
    ],
    "key_sequence": [
        "key.attack",
        "key.attack",
        "key.jump"
    ]
}
